CREATE OR REPLACE FUNCTION public.company_app_product_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT id FROM public.platform_products WHERE slug='fieldbridge' OR (active AND (SELECT count(*) FROM public.platform_products WHERE active)=1) ORDER BY (slug='fieldbridge') DESC LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.company_app_product_id() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.company_app_product_id() TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.start_company_trial() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$ DECLARE p public.platform_products; BEGIN SELECT * INTO p FROM public.platform_products WHERE id=public.company_app_product_id() AND active; IF FOUND THEN INSERT INTO public.platform_subscriptions(product_id,company_id,tenant_name,status,trial_ends_at) VALUES(p.id,NEW.id,NEW.name,'trial',now()+make_interval(days=>p.trial_days)); END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.company_module_access(_company uuid, _module text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ DECLARE s public.platform_subscriptions; p public.platform_products; o boolean; BEGIN SELECT * INTO p FROM public.platform_products WHERE id=public.company_app_product_id(); SELECT * INTO s FROM public.platform_subscriptions WHERE company_id=_company AND product_id=p.id LIMIT 1; IF NOT FOUND OR s.status='legacy' THEN RETURN true; END IF; IF s.status='trial' THEN RETURN s.trial_ends_at>now(); END IF; IF s.status<>'active' THEN RETURN false; END IF; IF NOT (_module=ANY(p.modules)) THEN RETURN true; END IF; SELECT enabled INTO o FROM public.platform_overrides WHERE subscription_id=s.id AND module=_module AND starts_at<=now() AND ends_at>now() ORDER BY created_at DESC LIMIT 1; IF FOUND THEN RETURN o; END IF; IF _module='core' THEN RETURN true; END IF; RETURN EXISTS(SELECT 1 FROM public.platform_catalog c WHERE c.product_id=p.id AND (c.id=s.plan_id OR c.id=ANY(s.pack_ids)) AND _module=ANY(c.modules)); END $$;
CREATE OR REPLACE FUNCTION public.my_commercial_status() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ DECLARE s public.platform_subscriptions; p public.platform_products; BEGIN SELECT * INTO p FROM public.platform_products WHERE id=public.company_app_product_id(); SELECT * INTO s FROM public.platform_subscriptions WHERE company_id=public.current_company_id() AND product_id=p.id LIMIT 1; IF NOT FOUND THEN RETURN jsonb_build_object('state','legacy','writable',true,'modules','[]'::jsonb); END IF; RETURN jsonb_build_object('state',CASE WHEN s.status='trial' AND s.trial_ends_at<=now() THEN 'read_only' ELSE s.status END,'trial_ends_at',s.trial_ends_at,'writable',public.company_module_access(s.company_id,'core'),'modules',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',m,'enabled',public.company_module_access(s.company_id,m))),'[]'::jsonb) FROM unnest(p.modules) m),'branding',(SELECT branding_required FROM public.platform_catalog WHERE id=s.plan_id)); END $$;